import {settingAnalysisPage} from './setting-analysis.js';
import {analysisPage} from './analysis.js';
import {createLineup} from './lineup.js';
import {repository} from './repository.js';
import {makePlayer,makeGame,filterGames,recordSummary,opponentRecords,cumulativeStats} from './services.js';
import {positions,matchFormats,formatFor,courtPositions,courtRows,statusLabels,today,escapeHTML as esc} from './config.js';
const repo=repository(),content=document.querySelector('#content');let chosen=[],lineup=createLineup(),focusedPlayer=null,editingPlayer=null,pendingConfirm=null;let period='all';const selectedPlayers=new Set();
const rate=v=>v===null?'−':v.toFixed(1)+'%';
const resultText=g=>g.result?`${g.result.wins}:${g.result.losses} ${g.result.outcome==='win'?'승':'패'}`:'−';
const badge=g=>`<span class="badge ${g.status}">${statusLabels[g.status]}</span>`;
const gameLink=g=>`#game/${g.id}`;
function alertStorage(){const el=document.querySelector('#storageAlert');el.textContent=repo.getError();el.hidden=!repo.getError();}
function heading(title,desc='',action=''){return `<div class="page-heading"><div><h1>${title}</h1>${desc?`<p>${desc}</p>`:''}</div>${action}</div>`;}
const newGameButton='<a class="button primary" href="#new-game">+ 새 경기</a>';
function summary(s){return `<div class="summary"><div><small>종료 경기</small><strong>${s.games}<span> 경기</span></strong></div><div><small>전적</small><strong>${s.wins}<span> 승</span> ${s.losses}<span> 패</span></strong></div><div><small>승률</small><strong>${rate(s.rate)}</strong></div><div><small>세트 전적</small><strong>${s.setWins}<span> 승</span> ${s.setLosses}<span> 패</span></strong></div></div>`;}
function gameTable(games){if(!games.length)return '<div class="empty">표시할 경기가 없습니다.<br>새 경기를 만들어 기록을 시작하세요.<br><a class="button primary" href="#new-game">+ 첫 경기 만들기</a></div>';return `<div class="table-wrap"><table><thead><tr><th>날짜</th><th>상대팀</th><th>경기명 / 대회</th><th>경기 방식</th><th>결과</th><th>상태</th><th></th></tr></thead><tbody>${games.map(g=>`<tr><td>${esc(g.date)}</td><td><a href="${gameLink(g)}">${esc(g.opponent)}</a></td><td>${esc(g.competition)}</td><td>${formatFor(g).label}</td><td class="${g.result?.outcome==='win'?'result-win':g.result?'result-loss':''}"><span class="result-pill">${resultText(g)}</span></td><td>${badge(g)}</td><td>${g.status==='completed'?`<a class="button" href="${gameLink(g)}">경기 상세</a>`:`<a class="button" href="record.html?game=${g.id}">${g.status==='scheduled'?'기록 시작':'기록 계속하기'}</a>`} <button class="danger" data-delete-game="${g.id}" aria-label="${esc(g.opponent)} 경기 삭제">삭제</button></td></tr>`).join('')}</tbody></table></div>`;}
function sorted(games){return [...games].sort((a,b)=>b.date.localeCompare(a.date)||b.createdAt.localeCompare(a.createdAt));}
function dashboard(){const {games}=repo.read(),done=filterGames(games),progress=sorted(games.filter(g=>g.status==='in_progress')),upcoming=games.filter(g=>g.status==='scheduled').sort((a,b)=>a.date.localeCompare(b.date));content.innerHTML=heading('대시보드','우리 팀의 경기와 기록을 한눈에 확인합니다.',newGameButton)+summary(recordSummary(done))+(progress.length?`<section class="panel"><div class="panel-heading"><h2>진행 중인 경기</h2><span class="muted small">${progress.length}경기</span></div>${gameTable(progress)}</section>`:'')+`<section class="panel"><div class="panel-heading"><h2>최근 경기</h2><div class="recent-outcomes">${done.slice(0,5).reverse().map(g=>`<span class="${g.result.outcome==='loss'?'loss':''}" title="${esc(g.date+' '+g.opponent)}">${g.result.outcome==='win'?'승':'패'}</span>`).join('')}<a class="inline-link" href="#games">전체 경기</a></div></div>${gameTable(done.slice(0,5))}</section>`+(upcoming.length?`<section class="panel"><div class="panel-heading"><h2>예정 경기</h2></div>${gameTable(upcoming.slice(0,3))}</section>`:`<section class="panel"><div class="next-game"><span class="muted">예정된 경기가 없습니다.</span><a class="inline-link" href="#new-game">경기 일정 등록</a></div></section>`);}
function gamesPage(opponent=''){const {games}=repo.read();content.innerHTML=heading(opponent?`${esc(opponent)} 상대 경기`:'경기 관리','예정·진행 중·종료 경기를 관리합니다.',newGameButton)+`<div class="filters"><input id="gameSearch" aria-label="경기 검색" placeholder="상대팀 또는 경기명 검색" value="${esc(opponent)}"><select id="statusFilter" aria-label="경기 상태"><option value="">모든 상태</option>${Object.entries(statusLabels).map(([v,l])=>`<option value="${v}">${l}</option>`).join('')}</select><span id="gameCount" class="muted"></span></div><section class="panel" id="gamesTable"></section>`;const update=()=>{const q=document.querySelector('#gameSearch').value.trim().toLowerCase(),status=document.querySelector('#statusFilter').value;let list=sorted(games).filter(g=>(!opponent||g.opponent===opponent)&&(!status||g.status===status)&&(!q||`${g.opponent} ${g.competition}`.toLowerCase().includes(q)));document.querySelector('#gameCount').textContent=`${list.length}경기`;document.querySelector('#gamesTable').innerHTML=gameTable(list)};document.querySelector('#gameSearch').oninput=update;document.querySelector('#statusFilter').onchange=update;update();}
function playerCount(games,id){return games.filter(g=>g.status==='completed'&&g.roster.some(p=>p.playerId===id)).length;}
function playersPage(){selectedPlayers.clear();const data=repo.read(),players=data.players.filter(p=>!p.deletedAt),games=data.games;content.innerHTML=heading('선수 관리','선수 정보와 활동 상태를 관리합니다.','<button class="primary" id="addPlayer">+ 선수 추가</button>')+`<div class="filters"><input id="playerSearch" aria-label="선수 검색" placeholder="이름 또는 등번호 검색"><select id="activeFilter" aria-label="활동 상태"><option value="">모든 선수</option><option value="true">활동</option><option value="false">비활성</option></select><span class="muted">${players.length}명</span><button class="danger" id="bulkDelete" disabled>선택 삭제 (0)</button></div><section class="panel" id="playersTable"></section>`;document.querySelector('#addPlayer').onclick=()=>openPlayer();const update=()=>{const q=document.querySelector('#playerSearch').value.trim(),filter=document.querySelector('#activeFilter').value;const list=players.filter(p=>(!q||`${p.name} ${p.number}`.includes(q))&&(!filter||String(p.active)===filter));document.querySelector('#playersTable').innerHTML=list.length?`<div class="table-wrap"><table><thead><tr><th><input type="checkbox" id="selectAllPlayers" aria-label="현재 표시 선수 전체 선택"></th><th>등번호</th><th>이름</th><th>포지션</th><th>소속</th><th>종료 경기</th><th>상태</th><th></th></tr></thead><tbody>${list.map(p=>`<tr><td><input type="checkbox" data-select-player="${p.id}" aria-label="${esc(p.name)} 선택" ${selectedPlayers.has(p.id)?'checked':''}></td><td>${esc(p.number||'−')}</td><td><a href="#player/${p.id}">${esc(p.name)}</a></td><td><span class="position-badge">${esc(p.position)}</span></td><td>${esc(p.affiliation||'−')}</td><td>${playerCount(games,p.id)}</td><td><span class="badge ${p.active?'completed':''}">${p.active?'활동':'비활성'}</span></td><td><button data-edit-player="${p.id}">수정</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">선수가 없습니다.</div>'};document.querySelector('#bulkDelete').onclick=()=>{const ids=[...selectedPlayers];if(!ids.length)return;confirmAction(`${ids.length}명의 선수를 삭제하시겠습니까?`,'경기 이력이 있는 선수는 목록에서 숨기고 과거 기록을 보존합니다. 이력이 없는 선수는 완전히 삭제합니다.',()=>{if(repo.deletePlayers(ids))return repo.flush?.().then(()=>route()).catch(()=>alertStorage())||route();else alertStorage();});document.querySelector('#applyConfirm').textContent='삭제';};document.querySelector('#playerSearch').oninput=update;document.querySelector('#activeFilter').onchange=update;update();}
function openPlayer(id){editingPlayer=id?repo.read().players.find(p=>p.id===id):null;const form=document.querySelector('#playerForm');form.reset();document.querySelector('#playerFormTitle').textContent=editingPlayer?'선수 수정':'선수 추가';document.querySelector('#positionOptions').innerHTML=positions.map(p=>`<option>${p}</option>`).join('');if(editingPlayer)for(const k of ['name','number','position','affiliation','active','memo'])form.elements[k].value=String(editingPlayer[k]);document.querySelector('#playerError').textContent='';document.querySelector('#deletePlayer').hidden=!editingPlayer;document.querySelector('#playerDialog').showModal();form.elements.name.focus();}
document.querySelector('#cancelPlayer').onclick=()=>document.querySelector('#playerDialog').close();document.querySelector('#playerForm').onsubmit=async e=>{e.preventDefault();try{const v=Object.fromEntries(new FormData(e.target));v.active=v.active==='true';const player=makePlayer(v,editingPlayer?.id);if(!repo.savePlayer(player))throw Error(repo.getError());await repo.flush?.();document.querySelector('#playerDialog').close();route();alertStorage()}catch(err){document.querySelector('#playerError').textContent=err.message}};
function newGamePage(editId){const db=repo.read(),existing=editId?db.games.find(g=>g.id===editId):null;if(editId&&!existing)return notFound();lineup=createLineup();focusedPlayer=null;chosen=[];
content.innerHTML=heading(existing?'경기 정보 수정':'새 경기','경기 정보를 입력하고 9인제 코트와 대기 선수를 구성하세요.')+`<form id="gameForm" class="form-panel"><section class="panel"><div class="panel-heading"><h2>경기 정보</h2><p>* 필수 입력</p></div><div class="form-grid"><label>경기 날짜 *<input type="date" name="date" required value="${existing?.date||today()}"></label><label>상대팀 *<input name="opponent" required maxlength="100" placeholder="예: 홍성" value="${esc(existing?.opponent||'')}"></label><label class="wide">경기명 / 대회명 *<input name="competition" required maxlength="150" placeholder="예: 충남 생활체육 배구대회" value="${esc(existing?.competition||'')}"></label><label>장소<input name="location" maxlength="150" value="${esc(existing?.location||'')}"></label><label>경기 방식<select name="format" ${existing?'disabled':''}>${Object.entries(matchFormats).map(([key,f])=>`<option value="${key}" ${(existing?formatFor(existing).maxSets===f.maxSets:key==='best_of_3')?'selected':''}>${f.label}</option>`).join('')}</select></label><label class="wide">메모<textarea name="memo" rows="2" maxlength="2000">${esc(existing?.memo||'')}</textarea></label></div></section>${existing?'':`<section class="panel"><div class="panel-heading"><h2>이번 경기 출전 선수</h2><span id="rosterCount" class="muted small">0명 선택</span></div><div class="nine-selection"><div><h3>활동 선수</h3><div class="player-options">${db.players.filter(p=>p.active&&!p.deletedAt).map(p=>`<label class="player-option"><input type="checkbox" value="${p.id}" data-roster><b>${esc(p.name)}</b><span>${esc(p.number?'#'+p.number+' · ':'')}${esc(p.position)}</span></label>`).join('')||'<div class="empty">선수 관리에서 활동 선수를 등록하세요.</div>'}</div></div><div id="lineupBoard"></div></div><p class="help-line" id="lineupHint" role="status">선수를 누른 뒤 이동할 코트 자리를 누르세요. 대기 선수와 코트 선수도 같은 방식으로 교환합니다.</p></section>`}<p id="gameError" class="error form-error" role="alert"></p><div class="form-actions"><a class="button" href="${existing?gameLink(existing):'#games'}">취소</a><button class="primary">${existing?'정보 저장':'경기 생성 · 기록 시작'}</button></div></form>`;
if(!existing){document.querySelectorAll('[data-roster]').forEach(input=>input.onchange=()=>{lineup.select(input.value,input.checked);if(!input.checked&&focusedPlayer===input.value)focusedPlayer=null;renderLineup()});renderLineup();}
document.querySelector('#gameForm').onsubmit=async e=>{e.preventDefault();try{const values=Object.fromEntries(new FormData(e.target));let game;if(existing){if(!values.opponent.trim()||!values.competition.trim()||!values.date)throw Error('필수 정보를 입력하세요.');game={...existing,...values,maxSets:existing.maxSets};if(!repo.saveGame(game))throw Error(repo.getError());await repo.flush?.();location.hash=gameLink(game)}else{const layout=lineup.entries();game=makeGame(values,repo.read().players,layout.map(p=>p.playerId),layout);if(!repo.saveGame(game))throw Error(repo.getError());await repo.flush?.();location.href=`record.html?game=${game.id}`}}catch(err){document.querySelector('#gameError').textContent=err.message;alertStorage()}};}
function renderLineup(){const {players}=repo.read(),l=lineup.read();chosen=l.selected;document.querySelector('#rosterCount').textContent=`코트 ${l.slots.filter(Boolean).length}/9명 · 대기 ${l.bench.length}명`;const chip=id=>{const p=players.find(x=>x.id===id);return `<span class="jersey">${esc(p.number?'#'+p.number:'−')}</span><b>${esc(p.name)}</b><small>${esc(p.position)}</small>`};document.querySelector('#lineupBoard').innerHTML=`<div class="court-heading"><h3>9인제 코트</h3><span class="muted small">3 × 3 배치</span></div><div class="nine-court"><div class="net-label">NET</div>${courtRows.map((label,row)=>`<div class="court-row"><span class="court-row-label">${label}</span>${Array.from({length:3},(_,col)=>{const i=row*3+col,id=l.slots[i];return `<button type="button" class="court-slot ${id?'occupied':''} ${id&&focusedPlayer===id?'picked':''}" data-court-index="${i}" aria-label="${label} ${['왼쪽','가운데','오른쪽'][col]}${id?' '+esc(players.find(p=>p.id===id).name):' 빈 자리'}" aria-pressed="${!!id&&focusedPlayer===id}">${id?chip(id):'<span class="empty-slot">＋<small>빈 자리</small></span>'}</button>`}).join('')}</div>`).join('')}</div><div class="bench-heading"><h3>대기 선수 <span class="muted small">${l.bench.length}명</span></h3><button type="button" class="bench-move" data-to-bench ${!focusedPlayer||!l.slots.includes(focusedPlayer)?'disabled':''}>선택 선수 대기로</button></div><div class="bench-seats">${l.bench.map(id=>`<button type="button" class="bench-chip ${focusedPlayer===id?'picked':''}" data-bench-player="${id}" aria-pressed="${focusedPlayer===id}">${chip(id)}</button>`).join('')||'<span class="muted small">코트 9명 이후 선택 선수는 여기에 배치됩니다.</span>'}</div>`;}
function gameDetail(id){const g=repo.getGame(id);if(!g)return notFound();const done=g.status==='completed';content.innerHTML=heading(`${esc(g.team)} ${g.result?`${g.result.wins} : ${g.result.losses}`:'vs'} ${esc(g.opponent)}`,`${esc(g.competition)} · ${esc(g.date)}`,`<div class="button-row"><button class="danger" data-delete-game="${g.id}">경기 삭제</button><a class="button" href="#edit-game/${g.id}">경기 정보 수정</a>${done?`<button class="primary" data-reopen="${g.id}">기록 수정</button>`:`<a class="button primary" href="record.html?game=${g.id}">${g.status==='scheduled'?'기록 시작':'기록 계속하기'}</a>`}</div>`)+`<div class="detail-info">${badge(g)}<span>${formatFor(g).label}</span><span>장소: ${esc(g.location||'미입력')}</span><span>출전 ${g.roster.length}명</span>${g.result?`<b class="${g.result.outcome==='win'?'result-win':'result-loss'}">${g.result.outcome==='win'?'승리':'패배'}</b>`:''}</div><div class="score-cards">${g.sets.map((s,i)=>`<div class="score-card"><small>${i+1}세트</small><strong>${s.score.some(v=>v>0)?s.score.join(' : '):'−'}</strong></div>`).join('')}</div>${g.memo?`<p class="muted">${esc(g.memo)}</p>`:''}<section class="panel"><div class="panel-heading"><h2>경기 기록</h2><a class="inline-link" href="record.html?game=${g.id}&view=1">기록표 크게 보기</a></div><iframe class="record-frame" title="경기 기록 조회" src="record.html?game=${g.id}&view=1"></iframe></section>`;}
function metricGroups(stats){const v=stats.values;const groups=[['공격',[['시도','P'],['득점','Q'],['차단','R'],['범실','S'],['성공률','T'],['득점률','U'],['효율','V']]],['리시브',[['시도','B'],['성공','C'],['정확','D'],['실패','E'],['효율','F']]],['서브',[['시도','AC'],['에이스','AF'],['실패','AG'],['성공률','AH'],['효율','AI'],['위협도','AJ']]],['블로킹',[['시도','X'],['차단 성공','Y'],['득점','Z'],['유효','AA'],['블럭 실패','AB']]],['수비',[['디그 성공','H'],['디그 실패','I'],['찬스볼 성공','J'],['어택커버 성공','L'],['디그 성공률','N'],['세트당 디그','O']]],['이단연결',[['시도','AK'],['오버','AL'],['언더','AM'],['공격가능 성공','AN'],['득점','AO'],['실패','AP'],['공격 불가','AQ']]]];const pct=['F','N','T','U','V','AH','AI','AJ'];return `<div class="player-metrics">${groups.map(([name,items])=>`<section class="metric-group"><h3>${name}</h3><dl>${items.map(([label,k])=>`<dt>${label}</dt><dd>${pct.includes(k)?rate(v[k]):v[k]===null?'−':Number.isInteger(v[k])?v[k]:v[k].toFixed(1)}</dd>`).join('')}</dl></section>`).join('')}</div>`;}
function playerDetail(id){const db=repo.read(),p=db.players.find(p=>p.id===id);if(!p)return notFound();const stats=cumulativeStats(db.games,id),games=filterGames(db.games).filter(g=>g.roster.some(x=>x.playerId===id));content.innerHTML=heading(esc(p.name),`${esc(p.position)} · ${p.number?'#'+esc(p.number)+' · ':''}${esc(p.affiliation)} · ${p.active?'활동':'비활성'}`,`<div class="button-row">${p.deletedAt?'<span class="badge">삭제된 선수 · 과거 기록</span>':`<button data-edit-player="${p.id}">선수 정보 수정</button><button class="danger" data-delete-player="${p.id}">선수 삭제</button>`}</div>`)+`<div class="summary"><div><small>종료 경기</small><strong>${stats.games}<span> 경기</span></strong></div><div><small>출전 세트</small><strong>${stats.setCount}<span> 세트</span></strong></div><div><small>공격 득점</small><strong>${stats.values.Q}</strong></div><div><small>서브 에이스</small><strong>${stats.values.AF}</strong></div></div>${p.memo?`<p class="player-meta">${esc(p.memo)}</p>`:''}${metricGroups(stats)}<section class="panel"><div class="panel-heading"><h2>출전 경기</h2></div>${gameTable(games)}</section><p class="muted small">출전 세트는 경기 명단에 포함되며 실제 점수가 입력된 세트를 기준으로 집계합니다.</p>`;}
function statsPage(){const db=repo.read(),games=filterGames(db.games,period),summaryData=recordSummary(games);content.innerHTML=heading('통계','종료 경기의 선수·팀 기록을 합산합니다.')+`<div class="filters"><label>기간 <select id="periodFilter"><option value="all" ${period==='all'?'selected':''}>전체</option><option value="year" ${period==='year'?'selected':''}>올해</option><option value="recent" ${period==='recent'?'selected':''}>최근 10경기</option></select></label><span class="muted">${games.length}경기</span></div>`+`<div class="page-heading"><h2>팀 누적 기록</h2><span class="muted small">퍼센트의 평균 대신 누적 기록으로 다시 계산</span></div>${metricGroups(cumulativeStats(games))}<section class="panel"><div class="panel-heading"><h2>선수별 누적 기록</h2></div><div class="table-wrap"><table><thead><tr><th>선수</th><th>경기</th><th>세트</th><th>공격 득점</th><th>공격 효율</th><th>리시브 효율</th><th>서브 에이스</th><th>블로킹 득점</th><th>디그</th></tr></thead><tbody>${db.players.map(p=>{const s=cumulativeStats(games,p.id);return `<tr><td><a href="#player/${p.id}">${esc(p.name)}</a></td><td>${s.games}</td><td>${s.setCount}</td><td>${s.values.Q}</td><td>${rate(s.values.V)}</td><td>${rate(s.values.F)}</td><td>${s.values.AF}</td><td>${s.values.Z}</td><td>${s.values.H}</td></tr>`}).join('')}</tbody></table></div></section>`;document.querySelector('#periodFilter').onchange=e=>{period=e.target.value;statsPage()};}
function confirmAction(title,text,callback){document.querySelector('#confirmTitle').textContent=title;document.querySelector('#confirmText').textContent=text;pendingConfirm=callback;document.querySelector('#applyConfirm').textContent='확인';document.querySelector('#confirmDialog').showModal();}
document.querySelector('#cancelConfirm').onclick=()=>document.querySelector('#confirmDialog').close();document.querySelector('#applyConfirm').onclick=()=>{document.querySelector('#confirmDialog').close();pendingConfirm?.();pendingConfirm=null;};
function deleteGame(id){const g=repo.getGame(id);if(!g)return;confirmAction(`${g.date} ${g.opponent} 경기를 삭제하시겠습니까?`,`${g.competition} 경기의 모든 세트 기록과 점수가 삭제됩니다. 전적과 선수 누적 통계에서도 제외되며 되돌릴 수 없습니다.`,async()=>{if(repo.deleteGame(id)){try{await repo.flush?.()}catch{alertStorage();return;}if(location.hash.startsWith('#game/'))location.hash='#games';else route();}else alertStorage();});document.querySelector('#applyConfirm').textContent='삭제';}
function deletePlayer(id){const p=repo.read().players.find(x=>x.id===id);if(!p)return;document.querySelector('#playerDialog').close();confirmAction(`${p.name} 선수를 삭제하시겠습니까?`,'경기에 등록된 선수는 목록에서 숨기고 과거 이름·포지션·기록을 보존합니다. 경기 이력이 없는 선수는 완전히 삭제합니다.',async()=>{try{const result=repo.deletePlayer(id);if(!result.saved)throw Error(repo.getError());await repo.flush?.();if(location.hash.startsWith('#player/'))location.hash='#players';else route();}catch(err){document.querySelector('#storageAlert').textContent=err.message;document.querySelector('#storageAlert').hidden=false;}});document.querySelector('#applyConfirm').textContent='삭제';}
document.querySelector('#deletePlayer').onclick=()=>deletePlayer(editingPlayer.id);
content.addEventListener('click',e=>{const gameRemove=e.target.closest('[data-delete-game]');if(gameRemove)deleteGame(gameRemove.dataset.deleteGame);const edit=e.target.closest('[data-edit-player]');if(edit)openPlayer(edit.dataset.editPlayer);const remove=e.target.closest('[data-delete-player]');if(remove)deletePlayer(remove.dataset.deletePlayer);
const court=e.target.closest('[data-court-index]'),bench=e.target.closest('[data-bench-player]'),toBench=e.target.closest('[data-to-bench]');if(court){const i=+court.dataset.courtIndex,id=lineup.read().slots[i];if(focusedPlayer){lineup.place(focusedPlayer,i);focusedPlayer=null;}else focusedPlayer=id;renderLineup();}if(bench){const id=bench.dataset.benchPlayer,slots=lineup.read().slots;if(focusedPlayer&&slots.includes(focusedPlayer)){lineup.place(id,slots.indexOf(focusedPlayer));focusedPlayer=null;}else focusedPlayer=focusedPlayer===id?null:id;renderLineup();}if(toBench&&focusedPlayer){lineup.toBench(focusedPlayer);focusedPlayer=null;renderLineup();}
const reopen=e.target.closest('[data-reopen]');if(reopen)confirmAction('기록 수정을 시작하시겠습니까?','경기를 진행 중으로 되돌립니다. 수정 후 다시 경기 종료를 누르면 전적과 통계에 반영됩니다.',async()=>{const g=repo.getGame(reopen.dataset.reopen);g.status='in_progress';g.result=null;if(repo.saveGame(g)&&await (repo.flush?.()||Promise.resolve(true)).then(()=>true).catch(()=>false))location.href=`record.html?game=${g.id}`;else alertStorage()});});
function notFound(){content.innerHTML=heading('기록을 찾을 수 없습니다.')+'<a class="button" href="#dashboard">대시보드로</a>';}
function route(){const hash=location.hash.slice(1)||'dashboard';const [page,...parts]=hash.split('/');const id=parts.join('/');const menu=page.includes('player')?'players':['games','game','new-game','edit-game','opponent'].includes(page)?'games':page==='stats'?'stats':page==='analysis'?'analysis':page==='setting-analysis'?'setting-analysis':'dashboard';document.querySelectorAll('[data-menu]').forEach(a=>a.classList.toggle('active',a.dataset.menu===menu));document.querySelector('#breadcrumb').textContent={dashboard:'대시보드',games:'경기 관리',players:'선수 관리',stats:'통계',analysis:'전술 분석','setting-analysis':'세팅 분석'}[menu];if(page==='dashboard')dashboard();else if(page==='games')gamesPage();else if(page==='players')playersPage();else if(page==='new-game')newGamePage();else if(page==='edit-game')newGamePage(id);else if(page==='game')gameDetail(id);else if(page==='player')playerDetail(id);else if(page==='stats')statsPage();else if(page==='analysis')analysisPage(content,repo.read());else if(page==='setting-analysis')settingAnalysisPage(content,repo.read());else if(page==='opponent')gamesPage(decodeURIComponent(id));else notFound();alertStorage();}
window.addEventListener('hashchange',route);window.addEventListener('pageshow',route);route();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_volleyball_summary',description:'선수 수, 경기 수 및 종료 경기의 팀 전적을 조회합니다.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:(input={})=>{if(!input||typeof input!=='object'||Object.keys(input).length)throw Error('입력 인자가 없는 조회 도구입니다.');const db=repo.read();return {players:db.players.length,games:db.games.length,record:recordSummary(db.games)}}})).catch(()=>{})}catch{}}

content.addEventListener('change',e=>{if(e.target.matches('[data-select-player]')){if(e.target.checked)selectedPlayers.add(e.target.dataset.selectPlayer);else selectedPlayers.delete(e.target.dataset.selectPlayer);}else if(e.target.id==='selectAllPlayers'){content.querySelectorAll('[data-select-player]').forEach(el=>{el.checked=e.target.checked;if(el.checked)selectedPlayers.add(el.dataset.selectPlayer);else selectedPlayers.delete(el.dataset.selectPlayer);});}else return;const inputs=[...content.querySelectorAll('[data-select-player]')],all=content.querySelector('#selectAllPlayers');all.checked=inputs.length>0&&inputs.every(el=>el.checked);all.indeterminate=inputs.some(el=>el.checked)&&!all.checked;const button=content.querySelector('#bulkDelete');button.disabled=!selectedPlayers.size;button.textContent=`선택 삭제 (${selectedPlayers.size})`;});
